"""Regenerate vendor/a_stock_data/core.py from a pinned a-stock-data SKILL.md.

The upstream project (Apache-2.0) ships its code as Python blocks inside SKILL.md.
This keeps only definitions (imports, functions, classes, UPPER/_private constants)
and drops example calls, so importing the module never touches the network.
Optional imports (mootdx, stockstats) are wrapped in try/except.

    python scripts/collect/vendor/build_a_stock_data.py SKILL.md <upstream commit sha>
"""
import ast, hashlib, json, re, sys
from pathlib import Path

src, commit = Path(sys.argv[1]), sys.argv[2]
text = src.read_text(encoding="utf-8")
out = []
for block in re.findall(r"```python\n(.*?)```", text, re.S):
    for node in ast.parse(block).body:
        keep = isinstance(node, (ast.Import, ast.ImportFrom, ast.FunctionDef, ast.ClassDef, ast.Try))
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            names = [t.id for t in targets if isinstance(t, ast.Name)]
            keep = bool(names) and len(names) == len(targets) and all(n.isupper() or n.startswith("_") for n in names)
        if keep:
            out.append(ast.get_source_segment(block, node))
code = "\n\n".join(out)
lines = []
for line in code.split("\n"):
    if re.match(r"^(from|import) (mootdx|stockstats)\b", line):
        lines.append("try:\n    " + line + "\nexcept ImportError:  # optional dependency\n    pass")
    else:
        lines.append(line)
code = "\n".join(lines)
ast.parse(code)
digest = hashlib.sha256(text.encode()).hexdigest()
header = (f'"""Vendored from simonlin1212/a-stock-data (Apache-2.0), commit {commit}.\n\n'
          f'Generated by scripts/collect/vendor/build_a_stock_data.py from SKILL.md sha256 {digest}.\n'
          'Do not edit by hand; see LICENSE and PROVENANCE.json in this directory.\n"""\n')
dest = Path(__file__).resolve().parent / "a_stock_data"
(dest / "core.py").write_text(header + code + "\n", encoding="utf-8")
(dest / "PROVENANCE.json").write_text(json.dumps({
    "upstream": "https://github.com/simonlin1212/a-stock-data", "commit": commit, "license": "Apache-2.0",
    "source_file": "SKILL.md", "source_sha256": digest,
    "extraction": "definitions only (imports, functions, classes, UPPER/_private constants); example calls dropped",
    "modifications": "optional imports mootdx/stockstats wrapped in try/except ImportError"}, ensure_ascii=False, indent=1) + "\n")
print(dest / "core.py", digest)
